<script setup lang="ts">
import { ref, reactive, computed, onMounted } from 'vue'
import { request } from '../api'
import { useSession } from '../stores/session'
import { useAsync } from '../composables/useAsync'
import { useTrace } from '../composables/useTrace'
import type { OpsSummary, Kind, Article, KnowledgeResult } from '../types'
import KnowledgePanel from '../components/KnowledgePanel.vue'
const store = useSession(), summary = ref<OpsSummary>(), initial = useAsync(), action = useAsync(), success = ref(''), verification = ref<KnowledgeResult>(), selectedSession = ref(store.activeId), filter = ref('')
const { events, state, error, connect, stop } = useTrace(store.activeId)
const sessions = computed(() => [...new Set(events.value.map(e => e.sessionId))])
const gaps = computed(() => events.value.filter(e => e.type === 'KNOWLEDGE_GAP'))
const handoffs = computed(() => events.value.filter(e => e.type.includes('HANDOFF')))
const shown = computed(() => [...events.value].reverse().filter(e => !filter.value || `${e.type} ${e.summary} ${e.sessionId}`.includes(filter.value)))
const form = reactive({title:'',topic:'',content:'',kind:'FACT' as Kind,source:'',keywords:'',claimKey:'',claimValue:''})
const load = () => initial.run(async () => { summary.value = await request<OpsSummary>('GET','/ops/summary',store.activeId); await connect() })
const add = () => action.run(async () => { const keywords = form.keywords.split(/[，,]/).map(k => k.trim()).filter(Boolean); if(!keywords.length) throw new Error('请至少填写一个关键词'); const article = await request<Article>('POST','/knowledge/add',store.activeId,{...form,keywords}); success.value = `已加入「${article.title}」，正在用关键词核验即时检索。`; verification.value = await request<KnowledgeResult>('GET','/knowledge/search',store.activeId,undefined,{q:keywords.join(' ')}); await load() })
const handoff = () => action.run(async () => { await request('POST','/ops/handoff',selectedSession.value,{reason:'需要人工核验礼仪与方案'}); success.value = '已记录人工接管申请；当前后端不提供工单分配或真实客服接入。'; await load() })
onMounted(load)
</script>
<template><div class="page"><div class="section-heading"><div><p class="eyebrow">掌柜案 · 每一条数字都有来处</p><h1>看见真实接待，不造热闹</h1></div><span class="tag">当前账号 · 会话追踪</span></div><p class="notice">统计仅覆盖 TraceBus 当前保留窗口（最多 5000 条、约 1 小时），非持久累计。统计与详细事件仅覆盖当前账号的本次问衣会话，不展示其他账号内容。</p><div class="actions"><span role="status">{{ state }}</span><button @click="stop">停止实时追踪</button><button :disabled="initial.loading.value" @click="load">刷新总览并重连</button></div><p v-if="error || initial.error.value" class="error" role="alert">{{ error || initial.error.value }}</p><p v-if="initial.loading.value" role="status">正在读取真实追踪…</p><div class="metrics"><article class="panel"><span>当前会话事件快照</span><strong>{{ summary?.events ?? '—' }}</strong><small>{{ summary?.source || '等待后端' }}</small></article><article class="panel"><span>流中会话数</span><strong>{{ sessions.length }}</strong><small>按会话标识去重</small></article><article class="panel"><span>知识盲区事件</span><strong>{{ gaps.length }}</strong><small>证据不足或冲突</small></article><article class="panel"><span>接管相关事件</span><strong>{{ handoffs.length }}</strong><small>申请与核验提示，非完成数</small></article></div><div class="two-column"><section class="panel"><h2>接待会话与人工摘要</h2><label for="handoff-session">选择真实会话</label><select id="handoff-session" v-model="selectedSession"><option :value="store.activeId">当前前端会话</option><option v-for="id in sessions.filter(id => id !== store.activeId)" :key="id" :value="id">{{ id }}</option></select><ul><li v-for="e in events.filter(e => e.sessionId === selectedSession).slice(-8)" :key="e.id">{{ e.type }} · {{ e.summary }}</li></ul><p class="muted">仅使用脱敏追踪摘要，不展示人像或身材数值。</p><button :disabled="action.loading.value" @click="handoff">登记人工接管申请</button><h3>知识盲区</h3><ol><li v-for="e in gaps.slice(-8).reverse()" :key="e.id">{{ new Date(e.timestamp).toLocaleTimeString('zh-CN') }} · {{ e.summary }}</li></ol><p v-if="!gaps.length">当前追踪窗口无知识盲区事件，不补造记录。</p></section><section class="panel"><h2>补一页新知 · 即时生效</h2><form @submit.prevent="add"><div class="form-grid"><label>标题<input v-model="form.title" required maxlength="120"></label><label>主题<input v-model="form.topic" required></label><label>知识性质<select v-model="form.kind"><option value="FACT">史实</option><option value="COMMON">通行说法</option></select></label><label>来源<input v-model="form.source" required></label><label>关键词（逗号分隔）<input v-model="form.keywords" required></label><label>断言标识<input v-model="form.claimKey" required></label><label>断言值<input v-model="form.claimValue" required></label></div><label for="knowledge-content">正文</label><textarea id="knowledge-content" v-model="form.content" rows="4" required maxlength="6000"/><p class="caption">同一断言标识的不同值可能触发冲突弃权。仅写入内存，重启丢失。</p><button class="primary" :disabled="action.loading.value">添加并检索验证</button></form><KnowledgePanel v-if="verification" :knowledge="verification"/></section></div><p v-if="success" class="notice" role="status">{{ success }}</p><p v-if="action.error.value" class="error" role="alert">{{ action.error.value }}，请修正或刷新后重试。</p><section class="panel section"><div class="between"><h2>实时事件簿</h2><label>筛选事件<input v-model="filter" placeholder="类型、摘要或会话"></label></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>会话</th><th>事件</th><th>脱敏摘要</th></tr></thead><tbody><tr v-for="e in shown" :key="e.id"><td>{{ new Date(e.timestamp).toLocaleString('zh-CN') }}</td><td>{{ e.sessionId }}</td><td>{{ e.type }}</td><td>{{ e.summary }}</td></tr></tbody></table></div><p v-if="!shown.length" class="state">当前没有匹配事件。</p></section></div></template>
